<template><section v-if="offer" class="pc-card"><p class="text-xs uppercase text-indigo-400">{{ $t('procPages.supplierOffer') }}</p><h1 class="mt-2 text-2xl font-bold text-white">{{ money(offer.price_minor, offer.currency) }}</h1><pre class="mt-5 overflow-auto rounded-lg bg-black/20 p-4 text-xs text-slate-300">{{ offer }}</pre></section><p v-else-if="error" class="pc-card text-red-300">{{ error }}</p></template>
<script setup lang="ts">
definePageMeta({ layout: 'procurement', middleware: ['auth'], alias: ['/buyer/offers/:id'] }); const route = useRoute(); const { getOffer } = useCommerce(); const offer = ref<any>(); const error = ref(''); const money = (value: number, currency: string) => new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(value / 100); onMounted(async () => { try { offer.value = await getOffer(String(route.params.id)) } catch (e: any) { error.value = e?.data?.detail || e?.message } })
</script>
